/**
 * Link version 1, frozen: the settings, overrides, profiles and schema channels.
 *
 * Written out as concrete types, copied from the shapes the app resolved when link version 1 was cut. It never
 * references the living types, so a change to a handler cannot move it. Do not edit this file to match a changed
 * handler: a change that breaks it needs a new LINK_VERSION and a new `contract/v<N>/` (see protocol.ts for the
 * rule). `tests/remote/contractV1.test.ts` checks the living types against it.
 */

import type { ChallengeValuesV1, EntryPinsV1 } from './shapesChallenges';
import type {
    ChallengeRecordV2V1,
    ConfigAppV1,
    ImportReportV1,
    ImportedV2V1,
    RuleMatchChallengeV1,
    SerializableSchemaEntryV1,
    SettingValuesV2V1,
    SettingsRecoveryV1,
    SettingsSaveDroppedV1,
    TitleRuleInfoV1,
    TitleRuleV1,
    WindowBoundsV1,
} from './shapesConfig';

export type SettingsChannelsV1 = {
    'acknowledge-import-report': { args: []; result: { success: false; error: string } | { success: true } };
    'apply-challenge-profile': {
        args: [name: unknown, challengeId: undefined | null | string | number];
        result: boolean;
    };
    'cleanup-stale-challenge-setting': {
        args: [activeChallengeIds: (string | number)[]];
        result: { success: false; error: string } | { success: false; error: 'invalid-args' } | { success: true };
    };
    'delete-challenge-profile': { args: [name: unknown]; result: boolean };
    'get-challenge-override': { args: [settingKey: string, challengeId: string | number]; result: unknown };
    'get-challenge-overrides': { args: [challengeId: string | number]; result: null | ChallengeValuesV1 };
    'get-challenge-profiles': { args: []; result: null | { [key: string]: ChallengeValuesV1 } };
    'get-effective-setting': {
        args: [settingKey: string, challengeId?: undefined | null | string | number];
        result: unknown;
    };
    'get-entry-pins': { args: [challengeId: string | number]; result: null | EntryPinsV1 };
    'get-environment-info': {
        args: [];
        result:
            | {
                  defaultMock: boolean;
                  platform:
                      | 'aix'
                      | 'android'
                      | 'darwin'
                      | 'freebsd'
                      | 'haiku'
                      | 'linux'
                      | 'openbsd'
                      | 'sunos'
                      | 'win32'
                      | 'cygwin'
                      | 'netbsd';
                  userDataPath: string;
                  isSourceCode: boolean;
                  isElectronPackaged: boolean;
                  isBuiltApp: boolean;
                  appName: string;
                  launchedAt: number;
                  nodeEnv: undefined | string;
                  dev: undefined | string;
                  prod: undefined | string;
              }
            | {
                  nodeEnv: string;
                  dev: undefined;
                  prod: undefined;
                  defaultMock: boolean;
                  platform:
                      | 'aix'
                      | 'android'
                      | 'darwin'
                      | 'freebsd'
                      | 'haiku'
                      | 'linux'
                      | 'openbsd'
                      | 'sunos'
                      | 'win32'
                      | 'cygwin'
                      | 'netbsd';
                  userDataPath: string;
                  launchedAt: undefined;
              };
    };
    'get-global-default': { args: [settingKey: string]; result: unknown };
    'get-import-report': {
        args: [];
        result: { success: false; error: string } | { success: true; report: null | ImportReportV1 };
    };
    'get-setting': { args: [key: string]; result: unknown };
    'get-settings': {
        args: [];
        result: {
            challenges: { [key: string]: ChallengeRecordV2V1 };
            rules: TitleRuleV1[];
            profiles: { [key: string]: unknown };
            defaults: SettingValuesV2V1;
            scenarios: { [key: string]: unknown };
            version: 2;
            app: ConfigAppV1;
            imported?: ImportedV2V1;
            seededProfiles: string[];
            hasToken: boolean;
        };
    };
    'get-settings-recovery': {
        args: [];
        result: { success: true; recovery: null | SettingsRecoveryV1 | SettingsSaveDroppedV1 };
    };
    'get-settings-schema': {
        args: [];
        result:
            | {
                  schema: { [key: string]: SerializableSchemaEntryV1 };
                  defaults: { [key: string]: unknown };
                  groups: { id: string; label: string; tier: string }[];
                  tiers: readonly { id: string; label: string }[];
                  profileLimits: { maxChallengeProfiles: number; maxProfileNameLength: number };
              }
            | { schema: {}; defaults: {}; groups?: undefined; tiers?: undefined; profileLimits?: undefined };
    };
    'get-third-party-notices': {
        args: [];
        result: { success: false; error: string } | { success: true; text: string };
    };
    'get-title-profile': {
        args: [target: string | RuleMatchChallengeV1, challengeId?: undefined | null | string | number];
        result: null | TitleRuleInfoV1;
    };
    'get-title-rules': { args: []; result: null | TitleRuleV1[] };
    'get-validation-error': {
        args: [
            settingKey: string,
            value: unknown,
            allSettings?: undefined | null | { [key: string]: unknown },
            challengeId?: undefined | null | string | number,
        ];
        result: null | string;
    };
    'is-global-default-modified': { args: [settingKey: string]; result: boolean };
    'is-setting-modified': { args: [key: string]; result: boolean };
    'remove-challenge-override': { args: [settingKey: string, challengeId: string]; result: boolean };
    'replace-challenge-overrides': {
        args: [challengeId: undefined | null | string | number, overrides: unknown, suppressTitleProfile?: unknown];
        result: boolean;
    };
    'reset-global-default': { args: [settingKey: string]; result: boolean };
    'reset-setting': { args: [key: string]; result: boolean };
    'save-challenge-profile': { args: [name: unknown, values: unknown]; result: boolean };
    'save-settings': {
        args: [
            newSettings: {
                [key: string]: unknown;
                mock?: boolean;
                onboardingCompleted?: boolean;
                windowBounds?: { login: WindowBoundsV1; main: WindowBoundsV1 };
                theme?: string;
                language?: string;
                timezone?: string;
                customTimezones?: string[];
                stayLoggedIn?: boolean;
                apiTimeout?: number;
                checkFrequencyMin?: number;
                checkFrequencyMax?: number;
                apiMaxRetries?: number;
                apiRetryBaseDelayMs?: number;
            },
        ];
        result: boolean;
    };
    'set-challenge-override': {
        args: [settingKey: string, challengeId: string | number, value: unknown];
        result: boolean;
    };
    'set-challenge-overrides': {
        args: [challengeId: undefined | null | string | number, overrides: unknown];
        result: boolean;
    };
    'set-entry-pin': {
        args: [kind: 'boost' | 'turbo', challengeId: string | number, imageId: null | string];
        result: { success: false; error: string } | { success: false; error: 'invalid-args' } | { success: true };
    };
    'set-global-default': { args: [settingKey: string, value: unknown]; result: boolean };
    'set-setting': { args: [key: string, value: unknown]; result: boolean };
    'set-title-rules': { args: [rules: unknown]; result: boolean };
};
